insert into faqs (question, answer, category, display_order) values
($q$Where is CSMP IAS coaching located in Lucknow?$q$, $q$We are located in the heart of Gomti Nagar, near the main market. Our center is easy to reach by auto, tempo, or metro. Visit us at 3/186, Vivek Khand 2, Gomti Nagar, Lucknow, Uttar Pradesh 226010.$q$, 'general', 1),
($q$Which is the best IAS coaching in Gomti Nagar?$q$, $q$CSMP IAS is rated as the best IAS coaching in Gomti Nagar because of our personal mentorship, small batch size (50 students), and experienced teachers from Delhi.$q$, 'general', 2),
($q$Is Gomti Nagar a good place for UPSC preparation?$q$, $q$Yes! Gomti Nagar is a peaceful and safe area for students. It has many libraries, bookstores, and good hostels nearby, making it perfect for serious studies.$q$, 'general', 3),
($q$How can I book a free demo class?$q$, $q$You can book a free demo class by calling us at +91 8887039761 or filling out the form on this website. You can also reach us on WhatsApp at the same number. Come and sit in a real class to see how we teach.$q$, 'general', 4),
($q$Do you offer online classes for students outside Lucknow?$q$, $q$Yes, we have a hybrid model. If you cannot come to Gomti Nagar, you can watch live classes on our App from your home.$q$, 'general', 5),
($q$What are the office timings for admission?$q$, $q$Our admission office in Gomti Nagar is open from 9:00 AM to 7:00 PM, Monday to Sunday. For queries, you can email us at contact@csmpias.com.$q$, 'general', 6),
($q$Is there a hostel facility near the coaching center?$q$, $q$Yes, there are many safe and affordable hostels and PGs for boys and girls within 500 meters of our Gomti Nagar center. Our team will help you find a room.$q$, 'general', 7),
($q$Can I speak to a teacher before joining?$q$, $q$Yes, we allow you to meet our senior mentors before paying fees. We believe in transparency. Feel free to contact us at +91 8887039761 or email contact@csmpias.com to schedule a meeting.$q$, 'general', 8),

($q$What subjects are covered in the GS Foundation Course?$q$, $q$We cover everything: History, Geography, Polity, Economy, Environment, Science & Tech, Ethics, and Essay. We also include CSAT coaching.$q$, 'course-details', 9),
($q$Do you provide coaching for CSAT?$q$, $q$Yes, CSAT is part of our full course. We teach Math, Reasoning, and English from the basics so that even Arts students can pass easily.$q$, 'course-details', 10),
($q$What is the duration of the IAS course?$q$, $q$The complete foundation course takes 10 to 12 months. Classes are held 5 to 6 days a week.$q$, 'course-details', 11),
($q$Do you provide printed study material?$q$, $q$Yes, every student gets a set of 12 printed books and monthly current affairs magazines. You do not need to buy extra books from the market.$q$, 'course-details', 12),
($q$What is the batch size at CSMP Lucknow?$q$, $q$We strictly keep only 50 students per batch. This ensures that the teacher can focus on every single student.$q$, 'course-details', 13),
($q$If I miss a class, how can I cover it?$q$, $q$Don't worry. All offline classes are recorded. You will get access to the video on our Student App for revision.$q$, 'course-details', 14),
($q$Do you conduct current affairs classes?$q$, $q$Yes, we have a special Current Affairs class every weekend to cover news from The Hindu and Indian Express newspapers.$q$, 'course-details', 15),
($q$Is this course for Prelims or Mains?$q$, $q$It is an Integrated Course. We prepare you for both Prelims and Mains together because the syllabus is connected.$q$, 'course-details', 16),

($q$What is the fee for IAS coaching in Lucknow?$q$, $q$To know the current fee structure for the GS Foundation Course, please contact our admission counseling team directly. You can call or WhatsApp us at +91 8887039761 or email contact@csmpias.com.$q$, 'fees-scholarships', 17),
($q$Can I pay the fee in installments (EMI)?$q$, $q$Yes, we offer an easy installment plan. Please reach out to our administration office at +91 8887039761 to understand the payment schedule and EMI options.$q$, 'fees-scholarships', 18),
($q$Do you offer any scholarships?$q$, $q$Yes, we conduct a Scholarship Test every Sunday. You can avail a scholarship on your tuition fees based on your performance in the test.$q$, 'fees-scholarships', 19),
($q$Is the study material fee included?$q$, $q$Yes, the course fee is comprehensive and includes all books, notes, bag, and test series. There are absolutely no hidden charges.$q$, 'fees-scholarships', 20),
($q$Is there a discount for one-time payment?$q$, $q$Yes, if you pay the full amount at the time of admission, you are eligible for a special discount. Please contact the front desk for details.$q$, 'fees-scholarships', 21),
($q$Do I get a refund if I leave the course?$q$, $q$We have a transparent refund policy for the initial days of the course. Please read our admission form or contact our office for specific terms and conditions.$q$, 'fees-scholarships', 22),
($q$Is the test series charged separately?$q$, $q$No, the Class Test Series (Weekly Prelims + Fortnightly Mains) is completely free for our classroom students.$q$, 'fees-scholarships', 23),
($q$Do you have special discounts for female students?$q$, $q$Yes, to support girl child education, we offer an additional discount for female aspirants. Please inquire at the time of admission.$q$, 'fees-scholarships', 24),

($q$I am a beginner. How should I start UPSC preparation?$q$, $q$Start by reading NCERT books (Class 6 to 12) for History and Geography. Also, start reading a daily newspaper like 'The Hindu'.$q$, 'preparation-tips', 25),
($q$How many hours should I study daily?$q$, $q$Consistency is key. Studying 6 to 8 hours daily with full focus is enough to crack the exam.$q$, 'preparation-tips', 26),
($q$Is it necessary to join coaching for IAS?$q$, $q$Self-study is possible, but coaching gives you a structured plan, expert guidance, and a competitive environment which speeds up your preparation.$q$, 'preparation-tips', 27),
($q$How can I improve my answer writing skills?$q$, $q$Start writing one answer daily. At CSMP Lucknow, we check your answers every day and tell you how to improve.$q$, 'preparation-tips', 28),
($q$Which newspaper is best for UPSC?$q$, $q$We recommend The Hindu or The Indian Express. Focus on the Editorial page and National news.$q$, 'preparation-tips', 29),
($q$When should I start preparing for Optional Subject?$q$, $q$You should start your Optional subject preparation 3 months after starting your GS preparation.$q$, 'preparation-tips', 30),
($q$Is coaching available for working professionals?$q$, $q$Yes, we have a special Weekend Batch (Saturday & Sunday) and early morning batches for working people.$q$, 'preparation-tips', 31),
($q$Can an average student crack the IAS exam?$q$, $q$Absolutely. UPSC looks for hard work and discipline, not just toppers. Many average students become IAS officers every year with the right guidance.$q$, 'preparation-tips', 32),

($q$What is the 'Mentorship' program at CSMP?$q$, $q$Every student gets a personal Mentor. You can sit with your mentor 1-on-1 to discuss your stress, study plan, and weak areas.$q$, 'mentorship-support', 33),
($q$How are doubts cleared?$q$, $q$You can ask doubts in the class. After class, teachers are available for 30 minutes. You can also message your mentor anytime.$q$, 'mentorship-support', 34),
($q$Do you conduct Mock Interviews?$q$, $q$Yes, after you clear Mains, we provide free Mock Interviews with retired IAS/IPS officers to prepare you for the final stage.$q$, 'mentorship-support', 35),
($q$Is the library facility available?$q$, $q$Yes, we have a quiet Reading Room / Library at our Gomti Nagar center open from 8 AM to 8 PM for students.$q$, 'mentorship-support', 36),
($q$Do you provide psychological support?$q$, $q$Yes, exam preparation is stressful. Our mentors act as a support system to keep you motivated and positive throughout the journey.$q$, 'mentorship-support', 37),
($q$How do you track my progress?$q$, $q$We use a Monthly Performance Report. We track your test marks and attendance to see if you are improving or not.$q$, 'mentorship-support', 38),
($q$Can I access the library on weekends?$q$, $q$Yes, the library is open on Saturdays and Sundays for self-study.$q$, 'mentorship-support', 39),
($q$What happens if I fail to clear the exam this year?$q$, $q$We support our students until they succeed. You can continue to use the library and consult mentors even after your course ends.$q$, 'mentorship-support', 40);
